+import { test } from "node:test";
+import assert from "node:assert/strict";
+import { hashPassword, verifyPassword, login } from "../src/auth.js";
+
+test("hashPassword returns salt:hash, never plaintext, random salt", () => {
+  const h = hashPassword("hunter2");
+  assert.match(h, /^[0-9a-f]{32}:[0-9a-f]+$/);
+  assert.ok(!h.includes("hunter2"));
+  assert.notEqual(hashPassword("same"), hashPassword("same"));
+});
+
+test("hashPassword throws on empty or non-string input", () => {
+  assert.throws(() => hashPassword(""));
+  assert.throws(() => hashPassword(null));
+});
+
+test("verifyPassword accepts correct and rejects wrong password", () => {
+  const stored = hashPassword("s3cret-pw");
+  assert.equal(verifyPassword("s3cret-pw", stored), true);
+  assert.equal(verifyPassword("wrong", stored), false);
+});
+
+test("verifyPassword rejects malformed stored values", () => {
+  assert.equal(verifyPassword("x", ""), false);
+  assert.equal(verifyPassword("x", "noseparator"), false);
+  assert.equal(verifyPassword("x", "zz:zz"), false);
+  assert.equal(verifyPassword(null, "a:b"), false);
+});
+
+test("login succeeds with valid credentials via injected lookup", () => {
+  const passwordHash = hashPassword("pw123456");
+  const findUser = (u) => (u === "alice" ? { passwordHash } : null);
+  const ok = login("alice", "pw123456", findUser);
+  assert.equal(ok.success, true);
+  assert.ok(typeof ok.token === "string" && ok.token.length === 64);
+  // token is random, not a hardcoded prefix
+  assert.ok(!ok.token.startsWith("hardcoded"));
+  assert.notEqual(ok.token, login("alice", "pw123456", findUser).token);
+});
+
+test("login fails for missing user, wrong password, or empty input", () => {
+  const passwordHash = hashPassword("correct");
+  const findUser = (u) => (u === "alice" ? { passwordHash } : null);
+  assert.equal(login("nobody", "correct", findUser).success, false);
+  assert.equal(login("alice", "wrong", findUser).success, false);
+  assert.equal(login("", "pw", findUser).success, false);
+  assert.equal(login("alice", "", findUser).success, false);
+  assert.equal(login("alice", "pw").success, false); // no findUser
+});
