+import { test } from "node:test";
+import assert from "node:assert/strict";
+import { createUser, deleteUser, listUsers } from "../src/users.js";
+
+function mockRes() {
+  const res = { statusCode: 200, body: null };
+  res.status = (code) => {
+    res.statusCode = code;
+    return res;
+  };
+  res.json = (data) => {
+    res.body = data;
+    return res;
+  };
+  return res;
+}
+
+test("createUser stores a password hash, never plaintext", () => {
+  const res = mockRes();
+  createUser({ body: { username: "alice", email: "a@b.com", password: "secret123" } }, res);
+  assert.equal(res.statusCode, 200);
+  assert.ok(res.body.passwordHash);
+  assert.equal(res.body.password, undefined);
+  assert.ok(!JSON.stringify(res.body).includes("secret123"));
+});
+
+test("createUser rejects missing fields with 400", () => {
+  const res = mockRes();
+  createUser({ body: { username: "alice" } }, res);
+  assert.equal(res.statusCode, 400);
+  assert.ok(res.body.error);
+});
+
+test("createUser handles a missing body", () => {
+  const res = mockRes();
+  createUser({}, res);
+  assert.equal(res.statusCode, 400);
+});
+
+test("deleteUser returns a parameterized query (no concatenation)", () => {
+  const res = mockRes();
+  deleteUser({ params: { id: "42" } }, res);
+  assert.equal(res.body.deleted, true);
+  const q = res.body.query;
+  assert.equal(q.params[0], "42");
+  assert.match(q.text, /\$1/);
+  assert.ok(!q.text.includes("42"));
+});
+
+test("deleteUser keeps an injection payload out of the SQL text", () => {
+  const res = mockRes();
+  const evil = "1 OR 1=1";
+  deleteUser({ params: { id: evil } }, res);
+  assert.equal(res.body.query.params[0], evil);
+  assert.equal(res.body.query.text.includes("OR"), false);
+});
+
+test("listUsers returns an array", () => {
+  const res = mockRes();
+  listUsers({}, res);
+  assert.ok(Array.isArray(res.body));
+});

