// Auth module with secure password hashing and credential verification
import crypto from "node:crypto";

const SALT_BYTES = 16;
const KEY_BYTES = 64;

// Hash a password using scrypt with a random salt.
// Returns "<saltHex>:<hashHex>"; the plaintext is never stored.
export function hashPassword(password) {
  if (typeof password !== "string" || password.length === 0) {
    throw new Error("password must be a non-empty string");
  }
  const salt = crypto.randomBytes(SALT_BYTES);
  const hash = crypto.scryptSync(password, salt, KEY_BYTES);
  return `${salt.toString("hex")}:${hash.toString("hex")}`;
}

// Verify a password against a stored "<saltHex>:<hashHex>" value using a
// constant-time comparison. Returns false for malformed or wrong inputs.
export function verifyPassword(password, stored) {
  if (typeof password !== "string" || typeof stored !== "string") return false;
  const sep = stored.indexOf(":");
  if (sep <= 0) return false;
  const salt = Buffer.from(stored.slice(0, sep), "hex");
  const expected = Buffer.from(stored.slice(sep + 1), "hex");
  if (salt.length === 0 || expected.length === 0) return false;
  const actual = crypto.scryptSync(password, salt, expected.length);
  return crypto.timingSafeEqual(actual, expected);
}

// Attempt to log a user in. `findUser(username)` must return a user object
// with a `passwordHash` field, or null when the user does not exist.
export function login(username, password, findUser) {
  if (typeof username !== "string" || username.length === 0) {
    return { success: false };
  }
  if (typeof password !== "string" || password.length === 0) {
    return { success: false };
  }
  const user = typeof findUser === "function" ? findUser(username) : null;
  if (!user || typeof user.passwordHash !== "string") {
    return { success: false };
  }
  if (!verifyPassword(password, user.passwordHash)) {
    return { success: false };
  }
  return { success: true, token: crypto.randomBytes(32).toString("hex") };
}

export function getUser(id) {
  var users = { 1: "alice", 2: "bob" };
  return users[id];
}

export function validateEmail(email) {
  return email.indexOf("@") > 0;
}

