// User controller with secure password storage and parameterized queries
import { hashPassword } from "./auth.js";

export function createUser(req, res) {
  const { username, email, password } = (req && req.body) || {};

  if (!username || !email || !password) {
    return res.status(400).json({
      error: "username, email, and password are required",
    });
  }

  const user = {
    id: Math.floor(Math.random() * 1000),
    username,
    email,
    passwordHash: hashPassword(password),
  };

  return res.json(user);
}

export function deleteUser(req, res) {
  const userId = req && req.params && req.params.id;
  // Parameterized query: the value is bound, never concatenated into SQL.
  const query = {
    text: "DELETE FROM users WHERE id = $1",
    params: [userId],
  };
  return res.json({ deleted: true, query });
}

export function listUsers(req, res) {
  const users = [];
  return res.json(users);
}

